{{define "index"}}{{template "header" .}}
  {{if .User}}
  <div class="filters">
    <a href="/" {{if not .Filter}}class="active"{{end}}>Все посты</a>
    <a href="/?filter=created" {{if eq .Filter "created"}}class="active"{{end}}>Мои посты</a>
    <a href="/?filter=liked" {{if eq .Filter "liked"}}class="active"{{end}}>Понравившиеся</a>
  </div>
  {{end}}
  <div class="filters">
    {{range .Categories}}
      <a href="/?category={{.ID}}" {{if eq $.CategoryID .ID}}class="active"{{end}}>{{.Name}}</a>
    {{end}}
  </div>

  {{if not .Posts}}
    <p class="muted">Пока нет постов.</p>
  {{end}}
  {{range .Posts}}
  <article class="post-card">
    <h2><a href="/posts/{{.ID}}">{{.Title}}</a></h2>
    <div class="post-meta">{{.Author}} · {{.CreatedAt.Format "02.01.2006 15:04"}}</div>
    {{if .Categories}}
    <div class="categories">
      {{range .Categories}}<span class="category-tag">{{.Name}}</span>{{end}}
    </div>
    {{end}}
    <div class="votes">
      <span>+{{.Likes}}</span>
      <span>-{{.Dislikes}}</span>
    </div>
  </article>
  {{end}}
{{template "footer" .}}{{end}}

:root {
  color-scheme: light dark;
  --border: #d8d3c8;
  --muted: #6b6b6b;
  --accent: #b5502f;
}

* { box-sizing: border-box; }

body {
  font-family: system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  margin: 0;
  color: #1b1b1b;
  background: #fbfaf7;
}

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
}

.site-header nav { display: flex; gap: 1rem; align-items: center; }
.site-header a, .link-button { color: var(--accent); text-decoration: none; }
.site-header a:hover, .link-button:hover { text-decoration: underline; }

.muted { color: var(--muted); }

.container {
  max-width: 720px;
  margin: 0 auto;
  padding: 1.5rem;
}

.inline { display: inline; }
.link-button {
  background: none;
  border: none;
  padding: 0;
  font: inherit;
  cursor: pointer;
}

.filters { display: flex; flex-wrap: wrap; gap: .5rem; margin-bottom: 1.5rem; }
.filters a {
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: .25rem .75rem;
  text-decoration: none;
  color: inherit;
  font-size: .85rem;
}
.filters a.active { background: var(--accent); color: #fff; border-color: var(--accent); }

.post-card, .comment {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem;
  margin-bottom: 1rem;
}

.post-card h2 { margin: 0 0 .25rem; font-size: 1.15rem; }
.post-card h2 a { color: inherit; text-decoration: none; }
.post-meta, .comment-meta { color: var(--muted); font-size: .85rem; margin-bottom: .5rem; }

.categories { display: flex; gap: .35rem; flex-wrap: wrap; margin-bottom: .5rem; }
.category-tag {
  background: #eee8de;
  border-radius: 999px;
  padding: .1rem .6rem;
  font-size: .75rem;
}

.votes { display: flex; gap: .5rem; align-items: center; margin-top: .5rem; }
.votes button {
  border: 1px solid var(--border);
  background: #fff;
  border-radius: 6px;
  padding: .2rem .6rem;
  cursor: pointer;
}
.votes button.active { background: var(--accent); color: #fff; border-color: var(--accent); }

form.stack { display: flex; flex-direction: column; gap: .75rem; max-width: 480px; }
form.stack label { font-size: .85rem; color: var(--muted); }
form.stack input, form.stack textarea {
  padding: .5rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  font: inherit;
}
form.stack textarea { min-height: 8rem; resize: vertical; }
form.stack button {
  align-self: flex-start;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 6px;
  padding: .5rem 1.25rem;
  cursor: pointer;
}

.checkbox-group { display: flex; gap: 1rem; flex-wrap: wrap; }
.checkbox-group label { display: flex; align-items: center; gap: .35rem; color: inherit; }

.error { color: #a53e2a; margin-bottom: 1rem; }

