:root {
  color-scheme: light;
  --bg: #f7f4ee;
  --surface: rgba(255, 252, 246, .78);
  --surface-strong: #fffaf1;
  --ink: #171514;
  --muted: #746f68;
  --border: rgba(38, 33, 28, .12);
  --accent: #0f0f0f;
  --accent-soft: #f0dfbf;
  --gold: #b9893b;
  --green: #396a58;
  --danger: #b44030;
  --shadow: 0 24px 70px rgba(34, 28, 20, .12);
  --radius: 24px;
}

* { box-sizing: border-box; }

html { min-height: 100%; }

body {
  min-height: 100vh;
  margin: 0;
  color: var(--ink);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.55;
  background:
    radial-gradient(circle at 12% -8%, rgba(255, 230, 177, .7), transparent 34rem),
    radial-gradient(circle at 88% 0%, rgba(196, 219, 207, .7), transparent 28rem),
    linear-gradient(135deg, #fbf7ef 0%, #f3eee5 48%, #faf7f0 100%);
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image: linear-gradient(rgba(24, 20, 16, .035) 1px, transparent 1px), linear-gradient(90deg, rgba(24, 20, 16, .035) 1px, transparent 1px);
  background-size: 42px 42px;
  mask-image: linear-gradient(to bottom, #000, transparent 80%);
}

a { color: inherit; text-decoration: none; }
a:hover { color: var(--gold); }

button, input, textarea { font: inherit; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 10;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  margin: 1rem auto 0;
  width: min(1120px, calc(100% - 2rem));
  padding: .7rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: rgba(255, 250, 241, .76);
  backdrop-filter: blur(18px);
  box-shadow: 0 12px 40px rgba(30, 24, 18, .08);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: .6rem;
  padding: .45rem .85rem;
  border-radius: 999px;
  font-weight: 800;
  letter-spacing: -.03em;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  color: #fff;
  background: radial-gradient(circle at 30% 20%, #e7c982, #161412 72%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.35);
}

.site-header nav { display: flex; gap: .35rem; align-items: center; flex-wrap: wrap; justify-content: flex-end; }
.site-header nav a, .link-button, .nav-user {
  border: 0;
  border-radius: 999px;
  padding: .55rem .85rem;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}
.site-header nav a:hover, .link-button:hover { background: rgba(15, 15, 15, .06); color: var(--ink); }
.nav-primary { background: var(--accent) !important; color: #fff !important; box-shadow: 0 8px 24px rgba(15,15,15,.18); }
.nav-user { color: var(--muted); background: rgba(255,255,255,.5); }

.container {
  position: relative;
  width: min(980px, calc(100% - 2rem));
  margin: 0 auto;
  padding: 2.2rem 0 4rem;
}

.hero {
  padding: 3.2rem 0 2rem;
  text-align: center;
}
.kicker {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  margin: 0 0 1rem;
  padding: .35rem .75rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255,255,255,.5);
  font-size: .88rem;
}
.hero h1, .page-title, article h1 {
  margin: 0;
  font-size: clamp(2.2rem, 7vw, 5rem);
  line-height: .95;
  letter-spacing: -.07em;
}
.hero p, .page-subtitle { max-width: 620px; margin: 1rem auto 0; color: var(--muted); font-size: 1.05rem; }

.filters {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: .55rem;
  margin: 0 0 1rem;
}
.filters + .filters { margin-bottom: 1.8rem; }
.filters a {
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: .55rem .9rem;
  background: rgba(255,255,255,.48);
  color: var(--muted);
  font-size: .9rem;
  transition: transform .18s ease, background .18s ease, color .18s ease;
}
.filters a:hover { transform: translateY(-1px); color: var(--ink); background: rgba(255,255,255,.85); }
.filters a.active { background: var(--accent); color: #fff; border-color: var(--accent); }

.empty, .auth-card, .editor-card, .post-card, .comment, article.post-detail {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  backdrop-filter: blur(18px);
  box-shadow: var(--shadow);
}

.empty { padding: 2rem; text-align: center; color: var(--muted); }

.post-list { display: grid; gap: 1rem; }
.post-card {
  position: relative;
  overflow: hidden;
  padding: 1.15rem;
  transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease;
}
.post-card::after {
  content: "";
  position: absolute;
  inset: auto -20% -60% 45%;
  height: 9rem;
  background: radial-gradient(circle, rgba(185,137,59,.18), transparent 65%);
}
.post-card:hover { transform: translateY(-2px); border-color: rgba(185,137,59,.38); box-shadow: 0 28px 80px rgba(34,28,20,.16); }
.post-card h2 { position: relative; margin: 0 0 .35rem; font-size: 1.35rem; letter-spacing: -.03em; }
.post-card p { color: var(--muted); }
.post-meta, .comment-meta { color: var(--muted); font-size: .88rem; margin-bottom: .75rem; }

.categories { display: flex; gap: .4rem; flex-wrap: wrap; margin: .75rem 0; }
.category-tag {
  border: 1px solid rgba(185,137,59,.22);
  border-radius: 999px;
  padding: .2rem .65rem;
  background: rgba(240,223,191,.5);
  color: #6f4e1e;
  font-size: .78rem;
  font-weight: 650;
}

.votes { display: flex; gap: .45rem; align-items: center; margin-top: .8rem; color: var(--muted); }
.votes span, .votes button {
  min-width: 2.6rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: .28rem .7rem;
  background: rgba(255,255,255,.55);
  color: var(--muted);
  text-align: center;
}
.votes button { cursor: pointer; }
.votes button:hover, .votes button.active { background: var(--accent); color: #fff; border-color: var(--accent); }

.inline { display: inline; }
.link-button { font: inherit; }
.muted { color: var(--muted); }
.error {
  margin: 0 0 1rem;
  border: 1px solid rgba(180,64,48,.2);
  border-radius: 16px;
  padding: .8rem 1rem;
  color: var(--danger);
  background: rgba(180,64,48,.08);
}

.auth-wrap, .editor-wrap { display: grid; place-items: start center; padding-top: 2rem; }
.auth-card, .editor-card { width: min(560px, 100%); padding: clamp(1.2rem, 4vw, 2rem); }
.page-title { font-size: clamp(2rem, 6vw, 3.7rem); }

form.stack { display: flex; flex-direction: column; gap: .9rem; margin-top: 1.2rem; }
form.stack label { display: grid; gap: .4rem; color: var(--muted); font-size: .9rem; font-weight: 650; }
form.stack input, form.stack textarea {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: .85rem 1rem;
  outline: none;
  color: var(--ink);
  background: rgba(255,255,255,.72);
}
form.stack input:focus, form.stack textarea:focus { border-color: rgba(185,137,59,.65); box-shadow: 0 0 0 4px rgba(185,137,59,.12); }
form.stack textarea { min-height: 11rem; resize: vertical; }
form.stack button {
  align-self: flex-start;
  border: 0;
  border-radius: 999px;
  padding: .8rem 1.25rem;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  box-shadow: 0 12px 28px rgba(15,15,15,.18);
}
form.stack button:hover { transform: translateY(-1px); }

fieldset {
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 1rem;
  background: rgba(255,255,255,.36);
}
legend { padding: 0 .35rem; color: var(--muted); font-weight: 700; }
.checkbox-group { display: flex; gap: .65rem; flex-wrap: wrap; }
.checkbox-group label {
  display: inline-flex !important;
  align-items: center;
  gap: .45rem !important;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: .45rem .7rem;
  background: rgba(255,255,255,.55);
  color: var(--ink) !important;
}

article.post-detail { padding: clamp(1.2rem, 4vw, 2.2rem); margin-bottom: 1.5rem; }
.post-content { white-space: pre-wrap; font-size: 1.05rem; }
.section-title { margin: 2rem 0 1rem; font-size: 1.5rem; letter-spacing: -.03em; }
.comment { padding: 1rem; margin-bottom: .8rem; box-shadow: none; }
.comment p { margin: 0; white-space: pre-wrap; }

@media (max-width: 680px) {
  .site-header { align-items: flex-start; border-radius: 24px; }
  .site-header, .site-header nav { flex-direction: column; }
  .site-header nav { align-items: stretch; width: 100%; }
  .site-header nav a, .link-button, .nav-user { width: 100%; text-align: center; }
  .container { width: min(100% - 1rem, 980px); padding-top: 1rem; }
  .hero { padding-top: 2rem; }
}

@media (prefers-color-scheme: dark) {
  :root {
    color-scheme: dark;
    --bg: #10100f;
    --surface: rgba(29, 28, 26, .76);
    --surface-strong: #24221f;
    --ink: #f5efe5;
    --muted: #aaa39a;
    --border: rgba(255, 244, 226, .12);
    --accent: #f5efe5;
    --accent-soft: rgba(185,137,59,.2);
    --shadow: 0 24px 70px rgba(0,0,0,.35);
  }
  body {
    background:
      radial-gradient(circle at 12% -8%, rgba(185,137,59,.35), transparent 32rem),
      radial-gradient(circle at 88% 0%, rgba(57,106,88,.35), transparent 30rem),
      #10100f;
  }
  .site-header, .filters a, .votes span, .votes button, form.stack input, form.stack textarea, fieldset, .checkbox-group label { background: rgba(28,27,25,.72); }
  .nav-primary, form.stack button, .filters a.active, .votes button:hover, .votes button.active { background: #f5efe5 !important; color: #111 !important; }
  .category-tag { color: #e6c889; background: rgba(185,137,59,.16); }
}

