{{define "index"}}{{template "header" .}}
  <section class="hero">
    <p class="kicker">✦ Пространство для спокойных обсуждений</p>
    <h1>Форум, который выглядит как свежий чат.</h1>
    <p>Читайте посты, выбирайте категории и продолжайте разговор без шума.</p>
  </section>

  {{if .User}}
  <div class="filters" aria-label="Фильтры постов">
    <a href="/" {{if not .Filter}}class="active"{{end}}>Все посты</a>
    <a href="/?filter=created" {{if eq .Filter "created"}}class="active"{{end}}>Мои посты</a>
    <a href="/?filter=liked" {{if eq .Filter "liked"}}class="active"{{end}}>Понравившиеся</a>
  </div>
  {{end}}
  <div class="filters" aria-label="Категории">
    {{range .Categories}}
      <a href="/?category={{.ID}}" {{if eq $.CategoryID .ID}}class="active"{{end}}>{{.Name}}</a>
    {{end}}
  </div>

  {{if not .Posts}}
    <div class="empty">Пока нет постов. {{if .User}}Создайте первый.{{else}}Войдите, чтобы начать обсуждение.{{end}}</div>
  {{end}}
  <div class="post-list">
  {{range .Posts}}
    <article class="post-card">
      <h2><a href="/posts/{{.ID}}">{{.Title}}</a></h2>
      <div class="post-meta">{{.Author}} · {{.CreatedAt.Format "02.01.2006 15:04"}}</div>
      {{if .Categories}}
      <div class="categories">
        {{range .Categories}}<span class="category-tag">{{.Name}}</span>{{end}}
      </div>
      {{end}}
      <div class="votes" aria-label="Рейтинг">
        <span>+{{.Likes}}</span>
        <span>-{{.Dislikes}}</span>
      </div>
    </article>
  {{end}}
  </div>
{{template "footer" .}}{{end}}

