:root {
  color-scheme: light;
  --color-primary: #097fe8;
  --color-primary-active: #005bab;
  --color-text-accent: #0075de;
  --color-background: #ffffff;
  --color-surface: #f6f5f4;
  --color-surface-muted: #f0efed;
  --color-text-primary: #000000;
  --color-text-muted: #615d59;
  --color-text-subtle: #a39e98;
  --color-text-inverse: #f6f5f4;
  --color-border: #dfdcd9;
  --color-dark-surface: #02093a;
  --color-focus-ring: rgba(35, 131, 226, .35);
  --elevation-card: rgba(25, 25, 25, .027) 0 8px 12px, rgba(25, 25, 25, .027) 0 2px 6px;
  --elevation-card-hover: rgba(0, 0, 0, .01) 0 1px 3px, rgba(0, 0, 0, .02) 0 3px 7px, rgba(0, 0, 0, .02) 0 7px 15px, rgba(0, 0, 0, .04) 0 14px 28px;

  --bg: var(--color-background);
  --surface: var(--color-surface);
  --surface-2: var(--color-surface-muted);
  --ink: var(--color-text-primary);
  --muted: var(--color-text-muted);
  --subtle: var(--color-text-subtle);
  --border: var(--color-border);
  --blue: var(--color-primary);
  --link: var(--color-text-accent);
  --danger: #a5483d;
  --shadow: var(--elevation-card);
  --shadow-hover: var(--elevation-card-hover);
}

* { box-sizing: border-box; }

body {
  margin: 0;
  color: var(--ink);
  background: var(--bg);
  font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

body::before {
  content: "";
  position: fixed;
  inset: 0 0 auto;
  height: 280px;
  pointer-events: none;
  background: linear-gradient(#f6f5f4, rgba(246,245,244,0));
  z-index: -1;
}

a { color: var(--link); text-decoration: none; }
a:hover { text-decoration: underline; }
button, input, textarea { font: inherit; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 12px 24px;
  border-bottom: 1px solid var(--border);
  background: rgba(255, 255, 255, .86);
  backdrop-filter: blur(12px);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--ink);
  font-weight: 600;
}
.brand:hover { text-decoration: none; }
.brand-mark {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 6px;
  color: #fff;
  background: #000;
  font-size: 14px;
}

.site-header nav { display: flex; align-items: center; gap: 4px; flex-wrap: wrap; justify-content: flex-end; }
.site-header nav a, .link-button, .nav-user {
  min-height: 36px;
  padding: 7px 12px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
}
.site-header nav a:hover, .link-button:hover { background: var(--surface); color: var(--ink); text-decoration: none; }
.nav-primary { background: var(--blue) !important; color: #fff !important; }
.nav-primary:hover { background: #006dd1 !important; }
.nav-user { background: var(--surface); color: var(--muted); cursor: default; }

.container {
  width: min(920px, calc(100% - 48px));
  margin: 0 auto;
  padding: 48px 0 64px;
}

.hero {
  margin: 0 0 48px;
  padding: 64px 48px;
  border-radius: 20px;
  background: var(--color-dark-surface);
  color: var(--color-text-inverse);
}
.kicker {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 16px;
  padding: 4px 8px;
  border-radius: 4px;
  color: var(--muted);
  background: var(--surface);
  font-size: 14px;
}
.hero .kicker {
  color: var(--color-text-inverse);
  background: rgba(246, 245, 244, .1);
}
.hero h1, .page-title, article h1 {
  margin: 0;
  color: var(--ink);
  font-size: clamp(40px, 7vw, 54px);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -.02em;
}
.hero h1 { color: var(--color-text-inverse); }
.hero p, .page-subtitle { max-width: 640px; margin: 12px 0 0; color: var(--muted); }
.hero p { color: rgba(246, 245, 244, .8); }

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0 0 12px;
}
.filters + .filters { margin-bottom: 32px; }
.filters a {
  padding: 6px 10px;
  border: 1px solid transparent;
  border-radius: 4px;
  background: var(--surface);
  color: var(--muted);
  font-size: 14px;
}
.filters a:hover { color: var(--ink); background: var(--surface-2); text-decoration: none; }
.filters a.active { border-color: #cfd6df; background: #edf6ff; color: #005bab; }

.empty, .post-card, .comment, .auth-card, .editor-card, article.post-detail {
  border: 1px solid var(--border);
  border-radius: 12px;
  background: #fff;
  box-shadow: var(--shadow);
}
.empty { padding: 24px; color: var(--muted); }
.post-list { display: grid; gap: 12px; }

.post-card {
  padding: 16px 20px;
  transition: transform .2s ease, box-shadow .2s ease, background-color .2s ease;
}
.post-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-hover); background: #fff; }
.post-card h2 { margin: 0 0 4px; font-size: 22px; line-height: 1.3; font-weight: 500; letter-spacing: -.01em; }
.post-card h2 a { color: var(--ink); }
.post-card h2 a:hover { color: var(--link); }
.post-meta, .comment-meta { margin-bottom: 8px; color: var(--muted); font-size: 14px; }

.categories { display: flex; flex-wrap: wrap; gap: 6px; margin: 12px 0; }
.category-tag {
  padding: 2px 8px;
  border-radius: 4px;
  background: #f4eeee;
  color: #6f4f46;
  font-size: 13px;
}

.votes { display: flex; align-items: center; gap: 8px; margin-top: 12px; color: var(--muted); }
.votes span, .votes button {
  min-width: 40px;
  padding: 4px 8px;
  border: 1px solid var(--border);
  border-radius: 4px;
  background: var(--surface);
  color: var(--muted);
  text-align: center;
}
.votes button { cursor: pointer; }
.votes button:hover { background: var(--surface-2); color: var(--ink); }
.votes button.active { border-color: #cfd6df; background: #edf6ff; color: #005bab; }

.auth-wrap, .editor-wrap { display: grid; place-items: start center; }
.auth-card, .editor-card { width: min(640px, 100%); padding: 32px; }
.page-title { font-size: clamp(32px, 6vw, 48px); }

form.stack { display: flex; flex-direction: column; gap: 16px; margin-top: 24px; }
form.stack label { display: grid; gap: 8px; color: var(--ink); font-size: 14px; font-weight: 500; }
form.stack input, form.stack textarea {
  width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--ink);
  background: #fff;
  outline: none;
}
form.stack input:focus, form.stack textarea:focus {
  border-color: #3681b1;
  box-shadow: rgba(35, 131, 226, .57) 0 0 0 1px inset, var(--color-focus-ring) 0 0 0 2px;
}
form.stack textarea { min-height: 176px; resize: vertical; }
form.stack button {
  align-self: flex-start;
  padding: 8px 16px;
  border: 0;
  border-radius: 4px;
  background: var(--blue);
  color: #fff;
  font-weight: 500;
  cursor: pointer;
}
form.stack button:hover { background: #006dd1; }

fieldset {
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
}
legend { padding: 0 4px; color: var(--muted); font-weight: 500; }
.checkbox-group { display: flex; flex-wrap: wrap; gap: 8px; }
.checkbox-group label {
  display: inline-flex !important;
  align-items: center;
  gap: 8px !important;
  padding: 6px 10px;
  border-radius: 4px;
  background: #fff;
  color: var(--muted) !important;
}

article.post-detail { padding: 32px; }
.post-content {
  margin-top: 24px;
  white-space: pre-wrap;
  font-size: 17px;

