.comment { padding: 16px 20px; margin-bottom: 12px; box-shadow: none; }
.comment p { margin: 0; white-space: pre-wrap; }

.inline { display: inline; }
.link-button { font: inherit; }
.muted { color: var(--muted); }
.error {
  margin: 16px 0 0;
  padding: 8px 12px;
  border: 1px solid #ead1cc;
  border-radius: 4px;
  color: var(--danger);
  background: #fbefed;
}

@media (max-width: 720px) {
  .site-header { position: static; align-items: flex-start; flex-direction: column; padding: 12px 16px; }
  .site-header nav { width: 100%; justify-content: flex-start; }
  .container { width: min(100% - 32px, 920px); padding: 32px 0 48px; }
  .hero { margin-top: 0; padding: 32px 24px; }
  .auth-card, .editor-card, article.post-detail { padding: 24px; }
}

arguments.content:
{{define "index"}}{{template "header" .}}
  <div class="page-head">
    <h1>Посты</h1>
  </div>

  <section class="filter-panel" aria-label="Фильтры">
    {{if .User}}
    <div class="filters">
      <a href="/" {{if not .Filter}}class="active"{{end}}>▦ Все</a>
      <a href="/?filter=created" {{if eq .Filter "created"}}class="active"{{end}}>✎ Мои</a>
      <a href="/?filter=liked" {{if eq .Filter "liked"}}class="active"{{end}}>♡ Лайки</a>
    </div>
    {{end}}
    <div class="filters">
      {{range .Categories}}
        <a href="/?category={{.ID}}" {{if eq $.CategoryID .ID}}class="active"{{end}}># {{.Name}}</a>
      {{end}}
    </div>
  </section>

  {{if not .Posts}}
    <div class="empty">Постов нет.</div>
  {{end}}
  <div class="post-list">
  {{range .Posts}}
    <article class="post-card">
      <h2><a href="/posts/{{.ID}}">{{.Title}}</a></h2>
      <div class="post-meta"><span>◉ {{.Author}}</span><span>◷ {{.CreatedAt.Format "02.01.2006 15:04"}}</span></div>
      {{if .Categories}}
      <div class="categories">
        {{range .Categories}}<span class="category-tag"># {{.Name}}</span>{{end}}
      </div>
      {{end}}
      <div class="votes" aria-label="Рейтинг">
        <span aria-label="Лайки">▲ {{.Likes}}</span>
        <span aria-label="Дизлайки">▼ {{.Dislikes}}</span>
      </div>
    </article>
  {{end}}
  </div>
{{template "footer" .}}{{end}}

