// Package handlers wires HTTP routes to the store and templates.
package handlers

import (
	"context"
	"net/http"

	"forum/internal/models"
	page "forum/internal/render"
	"forum/internal/store"
)

func render(w http.ResponseWriter, status int, name string, data any) {
	page.Page(w, status, name, data)
}

type Handlers struct {
	store *store.Store
}

func New(s *store.Store) *Handlers { return &Handlers{store: s} }

func (h *Handlers) Routes(mux *http.ServeMux) {
	mux.HandleFunc("GET /", h.withUser(h.listPosts))
	mux.HandleFunc("GET /register", h.withUser(h.registerForm))
	mux.HandleFunc("POST /register", h.withUser(h.register))
	mux.HandleFunc("GET /login", h.withUser(h.loginForm))
	mux.HandleFunc("POST /login", h.withUser(h.login))
	mux.HandleFunc("POST /logout", h.withUser(h.logout))

	mux.HandleFunc("GET /posts/new", h.withUser(h.requireAuth(h.newPostForm)))
	mux.HandleFunc("POST /posts", h.withUser(h.requireAuth(h.createPost)))
	mux.HandleFunc("GET /posts/{id}", h.withUser(h.showPost))
	mux.HandleFunc("POST /posts/{id}/comments", h.withUser(h.requireAuth(h.createComment)))
	mux.HandleFunc("POST /posts/{id}/like", h.withUser(h.requireAuth(h.votePost)))
	mux.HandleFunc("POST /comments/{id}/like", h.withUser(h.requireAuth(h.voteComment)))
}

type ctxKey int

const userCtxKey ctxKey = 0

func userFrom(r *http.Request) *models.User {
	u, _ := r.Context().Value(userCtxKey).(*models.User)
	return u
}

// withUser loads the session (if any) and attaches the user to the request context.
func (h *Handlers) withUser(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		cookie, err := r.Cookie("session")
		if err != nil {
			next(w, r)
			return
		}
		user, err := h.store.GetSessionUser(cookie.Value)
		if err != nil {
			next(w, r)
			return
		}
		ctx := context.WithValue(r.Context(), userCtxKey, user)
		next(w, r.WithContext(ctx))
	}
}

// requireAuth rejects the request with 401 when no session user is attached.
func (h *Handlers) requireAuth(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if userFrom(r) == nil {
			http.Error(w, "must be logged in", http.StatusUnauthorized)
			return
		}
		next(w, r)
	}
}

package render

import (
	"html/template"
	"io/fs"
	"net/http"
)

var tmpl *template.Template

func Load(templates fs.FS) error {
	t, err := template.ParseFS(templates, "*.html")
	if err != nil {
		return err
	}
	tmpl = t
	return nil
}

// Page executes the named top-level template ("index", "post", "login", ...).
func Page(w http.ResponseWriter, status int, name string, data any) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.WriteHeader(status)
	if err := tmpl.ExecuteTemplate(w, name, data); err != nil {
		http.Error(w, "template error: "+err.Error(), http.StatusInternalServerError)
	}
}

package main

import (
	"embed"
	"io/fs"
	"log"
	"net/http"
	"os"

	"forum/internal/db"
	"forum/internal/handlers"
	"forum/internal/render"
	"forum/internal/store"
)

//go:embed templates/*.html
var templatesFS embed.FS

//go:embed static
var staticFS embed.FS

func main() {
	dbPath := os.Getenv("FORUM_DB_PATH")
	if dbPath == "" {
		dbPath = "forum.db"
	}
	addr := os.Getenv("FORUM_ADDR")
	if addr == "" {
		addr = ":8080"
	}

	conn, err := db.Open(dbPath)
	if err != nil {
		log.Fatalf("open db: %v", err)
	}
	defer conn.Close()

	templates, err := fs.Sub(templatesFS, "templates")
	if err != nil {
		log.Fatalf("templates: %v", err)
	}
	if err := render.Load(templates); err != nil {
		log.Fatalf("parse templates: %v", err)
	}

	h := handlers.New(store.New(conn))
	mux := http.NewServeMux()
	h.Routes(mux)
	mux.Handle("GET /static/", http.FileServerFS(staticFS))

	log.Printf("forum listening on %s", addr)
	if err := http.ListenAndServe(addr, mux); err != nil {
		log.Fatal(err)
	}
}

package db

import (
	"database/sql"
	_ "embed"

	_ "modernc.org/sqlite"
)

//go:embed schema.sql
var schema string

func Open(path string) (*sql.DB, error) {
	conn, err := sql.Open("sqlite", path+"?_pragma=foreign_keys(1)")
	if err != nil {
		return nil, err
	}
	conn.SetMaxOpenConns(1) // modernc sqlite: avoid concurrent-write "database is locked"
	if _, err := conn.Exec(schema); err != nil {
		conn.Close()
		return nil, err
	}
	return conn, nil
}

// Package store holds all SQL access for the forum. Kept as plain
// database/sql queries — the schema is small enough that an ORM or query
// builder would add more indirection than it removes.
package store

import (
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"errors"
	"time"

	"forum/internal/models"
)

var ErrNotFound = errors.New("not found")

const sessionTTL = 24 * time.Hour

type Store struct {
	db *sql.DB
}

func New(db *sql.DB) *Store { return &Store{db: db} }

// --- Auth ---------------------------------------------------------------

func (s *Store) CreateUser(email, username, passwordHash string) (int64, error) {
	res, err := s.db.Exec(
		`INSERT INTO users (email, username, password_hash) VALUES (?, ?, ?)`,
		email, username, passwordHash,
	)
	if err != nil {
		return 0, err
	}
	return res.LastInsertId()
}

func (s *Store) EmailTaken(email string) (bool, error) {
	var n int
	err := s.db.QueryRow(`SELECT COUNT(*) FROM users WHERE email = ?`, email).Scan(&n)
	return n > 0, err
}

func (s *Store) GetUserByEmail(email string) (*models.User, error) {
	u := &models.User{}
	err := s.db.QueryRow(
		`SELECT id, email, username, password_hash, created_at FROM users WHERE email = ?`, email,
	).Scan(&u.ID, &u.Email, &u.Username, &u.PasswordHash, &u.CreatedAt)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	return u, err
}

func (s *Store) CreateSession(userID int64) (token string, expires time.Time, err error) {
	raw := make([]byte, 32)
	if _, err = rand.Read(raw); err != nil {
		return "", time.Time{}, err
	}
	token = hex.EncodeToString(raw)
	expires = time.Now().Add(sessionTTL)
	_, err = s.db.Exec(
		`INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)`,
		token, userID, expires,
	)
	return token, expires, err
}

func (s *Store) GetSessionUser(token string) (*models.User, error) {
	u := &models.User{}
	err := s.db.QueryRow(`
		SELECT u.id, u.email, u.username, u.password_hash, u.created_at
		FROM sessions se JOIN users u ON u.id = se.user_id
		WHERE se.token = ? AND se.expires_at > ?`,
		token, time.Now(),
	).Scan(&u.ID, &u.Email, &u.Username, &u.PasswordHash, &u.CreatedAt)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	return u, err
}

func (s *Store) DeleteSession(token string) error {
	_, err := s.db.Exec(`DELETE FROM sessions WHERE token = ?`, token)
	return err
}

// --- Categories -----------------------------------------------------------

func (s *Store) ListCategories() ([]models.Category, error) {
	rows, err := s.db.Query(`SELECT id, name FROM categories ORDER BY name`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var cats []models.Category
	for rows.Next() {
		var c models.Category
		if err := rows.Scan(&c.ID, &c.Name); err != nil {
			return nil, err
		}
		cats = append(cats, c)
	}
	return cats, rows.Err()
}

// --- Posts ------------------------------------------------------------

func (s *Store) CreatePost(userID int64, title, content string, categoryIDs []int64) (int64, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return 0, err
	}
	defer tx.Rollback()

	res, err := tx.Exec(
		`INSERT INTO posts (user_id, title, content) VALUES (?, ?, ?)`,
		userID, title, content,
	)
	if err != nil {
		return 0, err
	}
	postID, err := res.LastInsertId()
	if err != nil {
		return 0, err
	}
	for _, catID := range categoryIDs {
		if _, err := tx.Exec(
			`INSERT INTO post_categories (post_id, category_id) VALUES (?, ?)`, postID, catID,
		); err != nil {
			return 0, err
		}
	}
	return postID, tx.Commit()
}

// PostFilter selects which posts ListPosts returns. Zero value = all posts.
type PostFilter struct {
	CategoryID      int64 // 0 = any
	CreatedByUserID int64 // 0 = any
	LikedByUserID   int64 // 0 = any
	ViewerID        int64 // 0 = anonymous; used to fill Post.MyVote
}

func (s *Store) ListPosts(f PostFilter) ([]models.Post, error) {
	query := `
		SELECT DISTINCT p.id, p.user_id, u.username, p.title, p.content, p.created_at
		FROM posts p
		JOIN users u ON u.id = p.user_id`
	var args []any
	var where []string

	if f.CategoryID != 0 {
		query += ` JOIN post_categories pc ON pc.post_id = p.id`
		where = append(where, `pc.category_id = ?`)
		args = append(args, f.CategoryID)
	}
	if f.CreatedByUserID != 0 {
		where = append(where, `p.user_id = ?`)
		args = append(args, f.CreatedByUserID)
	}
	if f.LikedByUserID != 0 {
		query += ` JOIN post_likes pl ON pl.post_id = p.id AND pl.value = 1`
		where = append(where, `pl.user_id = ?`)
		args = append(args, f.LikedByUserID)
	}
	for i, cond := range where {
		if i == 0 {
			query += ` WHERE ` + cond
		} else {
			query += ` AND ` + cond
		}
	}
	query += ` ORDER BY p.created_at DESC`

	rows, err := s.db.Query(query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var posts []models.Post
	for rows.Next() {
		var p models.Post
		if err := rows.Scan(&p.ID, &p.UserID, &p.Author, &p.Title, &p.Content, &p.CreatedAt); err != nil {
			return nil, err
		}
		posts = append(posts, p)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	for i := range posts {
		if err := s.hydratePost(&posts[i], f.ViewerID); err != nil {
			return nil, err
		}
	}
	return posts, nil
}

func (s *Store) GetPost(id, viewerID int64) (*models.Post, error) {
	p := &models.Post{}
	err := s.db.QueryRow(`
		SELECT p.id, p.user_id, u.username, p.title, p.content, p.created_at
		FROM posts p JOIN users u ON u.id = p.user_id WHERE p.id = ?`, id,
	).Scan(&p.ID, &p.UserID, &p.Author, &p.Title, &p.Content, &p.CreatedAt)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	if err := s.hydratePost(p, viewerID); err != nil {
		return nil, err
	}
	return p, nil
}

func (s *Store) hydratePost(p *models.Post, viewerID int64) error {
	rows, err := s.db.Query(`
		SELECT c.id, c.name FROM categories c
		JOIN post_categories pc ON pc.category_id = c.id
		WHERE pc.post_id = ? ORDER BY c.name`, p.ID)
	if err != nil {
		return err
	}
	for rows.Next() {
		var c models.Category
		if err := rows.Scan(&c.ID, &c.Name); err != nil {
			rows.Close()
			return err
		}
		p.Categories = append(p.Categories, c)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return err
	}

	if err := s.db.QueryRow(
		`SELECT COALESCE(SUM(value = 1), 0), COALESCE(SUM(value = -1), 0) FROM post_likes WHERE post_id = ?`,
		p.ID,
	).Scan(&p.Likes, &p.Dislikes); err != nil {
		return err
	}

	if viewerID != 0 {
		var v int
		err := s.db.QueryRow(
			`SELECT value FROM post_likes WHERE post_id = ? AND user_id = ?`, p.ID, viewerID,
		).Scan(&v)
		if err != nil && !errors.Is(err, sql.ErrNoRows) {
			return err
		}
		p.MyVote = v
	}
	return nil
}

