func setSessionCookie(w http.ResponseWriter, r *http.Request, token string, expires time.Time) {
	http.SetCookie(w, &http.Cookie{
		Name:     "session",
		Value:    token,
		Path:     "/",
		Expires:  expires,
		HttpOnly: true,
		Secure:   r.TLS != nil,
		SameSite: http.SameSiteLaxMode,
	})
}

func clearSessionCookie(w http.ResponseWriter, r *http.Request) {
	http.SetCookie(w, &http.Cookie{
		Name:     "session",
		Value:    "",
		Path:     "/",
		Expires:  time.Unix(0, 0),
		HttpOnly: true,
		Secure:   r.TLS != nil,
		SameSite: http.SameSiteLaxMode,
	})
}

func (h *Handlers) registerForm(w http.ResponseWriter, r *http.Request) {
	render(w, http.StatusOK, "register", map[string]any{"User": userFrom(r)})
}

func (h *Handlers) register(w http.ResponseWriter, r *http.Request) {
	if err := r.ParseForm(); err != nil {
		http.Error(w, "bad form", http.StatusBadRequest)
		return
	}
	email := r.FormValue("email")
	username := r.FormValue("username")
	password := r.FormValue("password")

	fail := func(status int, msg string) {
		render(w, status, "register", map[string]any{
			"User": userFrom(r), "Error": msg,
			"Email": email, "Username": username,
		})
	}

	if _, err := mail.ParseAddress(email); err != nil {
		fail(http.StatusBadRequest, "Введите корректный email")
		return
	}
	if username == "" {
		fail(http.StatusBadRequest, "Введите имя пользователя")
		return
	}
	if len(password) < 8 {
		fail(http.StatusBadRequest, "Пароль должен быть не короче 8 символов")
		return
	}

	taken, err := h.store.EmailTaken(email)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	if taken {
		fail(http.StatusConflict, "Этот email уже зарегистрирован")
		return
	}

	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	userID, err := h.store.CreateUser(email, username, string(hash))
	if err != nil {
		fail(http.StatusConflict, "Имя пользователя уже занято")
		return
	}

	token, expires, err := h.store.CreateSession(userID)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	setSessionCookie(w, r, token, expires)
	http.Redirect(w, r, "/", http.StatusSeeOther)
}

func (h *Handlers) loginForm(w http.ResponseWriter, r *http.Request) {
	render(w, http.StatusOK, "login", map[string]any{"User": userFrom(r)})
}

func (h *Handlers) login(w http.ResponseWriter, r *http.Request) {
	if err := r.ParseForm(); err != nil {
		http.Error(w, "bad form", http.StatusBadRequest)
		return
	}
	email := r.FormValue("email")
	password := r.FormValue("password")

	invalid := func() {
		render(w, http.StatusUnauthorized, "login", map[string]any{
			"User": userFrom(r), "Error": "Неверный email или пароль", "Email": email,
		})
	}

	user, err := h.store.GetUserByEmail(email)
	if errors.Is(err, store.ErrNotFound) {
		invalid()
		return
	}
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	if bcrypt.CompareHashAndPassword([]byte(user.PasswordHash), []byte(password)) != nil {
		invalid()
		return
	}

	token, expires, err := h.store.CreateSession(user.ID)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	setSessionCookie(w, r, token, expires)
	http.Redirect(w, r, "/", http.StatusSeeOther)
}

func (h *Handlers) logout(w http.ResponseWriter, r *http.Request) {
	if cookie, err := r.Cookie("session"); err == nil {
		_ = h.store.DeleteSession(cookie.Value)
	}
	clearSessionCookie(w, r)
	http.Redirect(w, r, "/", http.StatusSeeOther)
}

