func (h *Handlers) listPosts(w http.ResponseWriter, r *http.Request) {
	user := userFrom(r)
	f := store.PostFilter{}
	if user != nil {
		f.ViewerID = user.ID
	}

	q := r.URL.Query()
	if v := q.Get("category"); v != "" {
		id, err := strconv.ParseInt(v, 10, 64)
		if err != nil {
			http.Error(w, "invalid category", http.StatusBadRequest)
			return
		}
		f.CategoryID = id
	}
	switch q.Get("filter") {
	case "created":
		if user == nil {
			http.Error(w, "must be logged in", http.StatusUnauthorized)
			return
		}
		f.CreatedByUserID = user.ID
	case "liked":
		if user == nil {
			http.Error(w, "must be logged in", http.StatusUnauthorized)
			return
		}
		f.LikedByUserID = user.ID
	}

	posts, err := h.store.ListPosts(f)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	categories, err := h.store.ListCategories()
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	render(w, http.StatusOK, "index", map[string]any{
		"User":       user,
		"Posts":      posts,
		"Categories": categories,
		"Filter":     q.Get("filter"),
		"CategoryID": f.CategoryID,
	})
}

func (h *Handlers) newPostForm(w http.ResponseWriter, r *http.Request) {
	categories, err := h.store.ListCategories()
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	render(w, http.StatusOK, "new_post", map[string]any{
		"User": userFrom(r), "Categories": categories,
	})
}

func (h *Handlers) createPost(w http.ResponseWriter, r *http.Request) {
	if err := r.ParseForm(); err != nil {
		http.Error(w, "bad form", http.StatusBadRequest)
		return
	}
	title := strings.TrimSpace(r.FormValue("title"))
	content := strings.TrimSpace(r.FormValue("content"))
	if title == "" || content == "" {
		http.Error(w, "title and content are required", http.StatusBadRequest)
		return
	}

	var categoryIDs []int64
	for _, v := range r.Form["categories"] {
		id, err := strconv.ParseInt(v, 10, 64)
		if err != nil {
			http.Error(w, "invalid category", http.StatusBadRequest)
			return
		}
		categoryIDs = append(categoryIDs, id)
	}

	user := userFrom(r)
	postID, err := h.store.CreatePost(user.ID, title, content, categoryIDs)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	http.Redirect(w, r, "/posts/"+strconv.FormatInt(postID, 10), http.StatusSeeOther)
}

func postIDFrom(r *http.Request) (int64, error) {
	return strconv.ParseInt(r.PathValue("id"), 10, 64)
}

func (h *Handlers) showPost(w http.ResponseWriter, r *http.Request) {
	id, err := postIDFrom(r)
	if err != nil {
		http.Error(w, "invalid post id", http.StatusBadRequest)
		return
	}
	user := userFrom(r)
	var viewerID int64
	if user != nil {
		viewerID = user.ID
	}

	post, err := h.store.GetPost(id, viewerID)
	if errors.Is(err, store.ErrNotFound) {
		http.Error(w, "post not found", http.StatusNotFound)
		return
	}
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	comments, err := h.store.ListComments(id, viewerID)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	render(w, http.StatusOK, "post", map[string]any{
		"User": user, "Post": post, "Comments": comments,
	})
}

