func voteValue(r *http.Request) (int, bool) {
	switch r.FormValue("value") {
	case "1":
		return 1, true
	case "-1":
		return -1, true
	default:
		return 0, false
	}
}

// redirectBack sends the user back where they came from, falling back to the
// forum root. Used after vote actions so the like/dislike counts refresh in
// place instead of dropping the visitor onto a bare JSON-less response.
func redirectBack(w http.ResponseWriter, r *http.Request, fallback string) {
	dest := r.Referer()
	if dest == "" {
		dest = fallback
	}
	http.Redirect(w, r, dest, http.StatusSeeOther)
}

func (h *Handlers) votePost(w http.ResponseWriter, r *http.Request) {
	postID, err := postIDFrom(r)
	if err != nil {
		http.Error(w, "invalid post id", http.StatusBadRequest)
		return
	}
	if err := r.ParseForm(); err != nil {
		http.Error(w, "bad form", http.StatusBadRequest)
		return
	}
	value, ok := voteValue(r)
	if !ok {
		http.Error(w, "value must be 1 or -1", http.StatusBadRequest)
		return
	}

	user := userFrom(r)
	if err := h.store.VotePost(user.ID, postID, value); err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	redirectBack(w, r, "/posts/"+strconv.FormatInt(postID, 10))
}

