func (h *Handlers) createComment(w http.ResponseWriter, r *http.Request) {
	postID, err := postIDFrom(r)
	if err != nil {
		http.Error(w, "invalid post id", http.StatusBadRequest)
		return
	}
	exists, err := h.store.PostExists(postID)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	if !exists {
		http.Error(w, "post not found", http.StatusNotFound)
		return
	}

	if err := r.ParseForm(); err != nil {
		http.Error(w, "bad form", http.StatusBadRequest)
		return
	}
	content := strings.TrimSpace(r.FormValue("content"))
	if content == "" {
		http.Error(w, "comment cannot be empty", http.StatusBadRequest)
		return
	}

	user := userFrom(r)
	if _, err := h.store.CreateComment(postID, user.ID, content); err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	http.Redirect(w, r, "/posts/"+strconv.FormatInt(postID, 10), http.StatusSeeOther)
}

// --- Comments ---------------------------------------------------------

func (s *Store) CreateComment(postID, userID int64, content string) (int64, error) {
	res, err := s.db.Exec(
		`INSERT INTO comments (post_id, user_id, content) VALUES (?, ?, ?)`,
		postID, userID, content,
	)
	if err != nil {
		return 0, err
	}
	return res.LastInsertId()
}

func (s *Store) ListComments(postID, viewerID int64) ([]models.Comment, error) {
	rows, err := s.db.Query(`
		SELECT c.id, c.post_id, c.user_id, u.username, c.content, c.created_at
		FROM comments c JOIN users u ON u.id = c.user_id
		WHERE c.post_id = ? ORDER BY c.created_at ASC`, postID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var comments []models.Comment
	for rows.Next() {
		var c models.Comment
		if err := rows.Scan(&c.ID, &c.PostID, &c.UserID, &c.Author, &c.Content, &c.CreatedAt); err != nil {
			return nil, err
		}
		comments = append(comments, c)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	for i := range comments {
		c := &comments[i]
		if err := s.db.QueryRow(
			`SELECT COALESCE(SUM(value = 1), 0), COALESCE(SUM(value = -1), 0) FROM comment_likes WHERE comment_id = ?`,
			c.ID,
		).Scan(&c.Likes, &c.Dislikes); err != nil {
			return nil, err
		}
		if viewerID != 0 {
			var v int
			err := s.db.QueryRow(
				`SELECT value FROM comment_likes WHERE comment_id = ? AND user_id = ?`, c.ID, viewerID,
			).Scan(&v)
			if err != nil && !errors.Is(err, sql.ErrNoRows) {
				return nil, err
			}
			c.MyVote = v
		}
	}
	return comments, nil
}

// --- Likes --------------------------------------------------------------

// VotePost sets the viewer's vote to value (1 or -1). Voting the same value
// again clears the vote (toggle off).
func (s *Store) VotePost(userID, postID int64, value int) error {
	var existing int
	err := s.db.QueryRow(
		`SELECT value FROM post_likes WHERE user_id = ? AND post_id = ?`, userID, postID,
	).Scan(&existing)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		_, err = s.db.Exec(
			`INSERT INTO post_likes (user_id, post_id, value) VALUES (?, ?, ?)`, userID, postID, value)
		return err
	case err != nil:
		return err
	case existing == value:
		_, err = s.db.Exec(`DELETE FROM post_likes WHERE user_id = ? AND post_id = ?`, userID, postID)
		return err
	default:
		_, err = s.db.Exec(
			`UPDATE post_likes SET value = ? WHERE user_id = ? AND post_id = ?`, value, userID, postID)
		return err
	}
}

func (s *Store) VoteComment(userID, commentID int64, value int) error {
	var existing int
	err := s.db.QueryRow(
		`SELECT value FROM comment_likes WHERE user_id = ? AND comment_id = ?`, userID, commentID,
	).Scan(&existing)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		_, err = s.db.Exec(
			`INSERT INTO comment_likes (user_id, comment_id, value) VALUES (?, ?, ?)`, userID, commentID, value)
		return err
	case err != nil:
		return err
	case existing == value:
		_, err = s.db.Exec(`DELETE FROM comment_likes WHERE user_id = ? AND comment_id = ?`, userID, commentID)
		return err
	default:
		_, err = s.db.Exec(
			`UPDATE comment_likes SET value = ? WHERE user_id = ? AND comment_id = ?`, value, userID, commentID)
		return err
	}
}

func (s *Store) PostExists(id int64) (bool, error) {
	var n int
	err := s.db.QueryRow(`SELECT COUNT(*) FROM posts WHERE id = ?`, id).Scan(&n)
	return n > 0, err
}

