// Package store holds all SQL access for the forum. Kept as plain
// database/sql queries — the schema is small enough that an ORM or query
// builder would add more indirection than it removes.
package store

import (
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"errors"
	"time"

	"forum/internal/models"
)

var ErrNotFound = errors.New("not found")

const sessionTTL = 24 * time.Hour

type Store struct {
	db *sql.DB
}

func New(db *sql.DB) *Store { return &Store{db: db} }

// --- Auth ---------------------------------------------------------------

func (s *Store) CreateUser(email, username, passwordHash string) (int64, error) {
	res, err := s.db.Exec(
		`INSERT INTO users (email, username, password_hash) VALUES (?, ?, ?)`,
		email, username, passwordHash,
	)
	if err != nil {
		return 0, err
	}
	return res.LastInsertId()
}

func (s *Store) EmailTaken(email string) (bool, error) {
	var n int
	err := s.db.QueryRow(`SELECT COUNT(*) FROM users WHERE email = ?`, email).Scan(&n)
	return n > 0, err
}

func (s *Store) GetUserByEmail(email string) (*models.User, error) {
	u := &models.User{}
	err := s.db.QueryRow(
		`SELECT id, email, username, password_hash, created_at FROM users WHERE email = ?`, email,
	).Scan(&u.ID, &u.Email, &u.Username, &u.PasswordHash, &u.CreatedAt)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	return u, err
}

func (s *Store) CreateSession(userID int64) (token string, expires time.Time, err error) {
	raw := make([]byte, 32)
	if _, err = rand.Read(raw); err != nil {
		return "", time.Time{}, err
	}
	token = hex.EncodeToString(raw)
	expires = time.Now().Add(sessionTTL)
	_, err = s.db.Exec(
		`INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)`,
		token, userID, expires,
	)
	return token, expires, err
}

func (s *Store) GetSessionUser(token string) (*models.User, error) {
	u := &models.User{}
	err := s.db.QueryRow(`
		SELECT u.id, u.email, u.username, u.password_hash, u.created_at
		FROM sessions se JOIN users u ON u.id = se.user_id
		WHERE se.token = ? AND se.expires_at > ?`,
		token, time.Now(),
	).Scan(&u.ID, &u.Email, &u.Username, &u.PasswordHash, &u.CreatedAt)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	return u, err
}

func (s *Store) DeleteSession(token string) error {
	_, err := s.db.Exec(`DELETE FROM sessions WHERE token = ?`, token)
	return err
}

// --- Categories -----------------------------------------------------------

func (s *Store) ListCategories() ([]models.Category, error) {
	rows, err := s.db.Query(`SELECT id, name FROM categories ORDER BY name`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var cats []models.Category
	for rows.Next() {
		var c models.Category
		if err := rows.Scan(&c.ID, &c.Name); err != nil {
			return nil, err
		}
		cats = append(cats, c)
	}
	return cats, rows.Err()
}

// --- Posts ------------------------------------------------------------

func (s *Store) CreatePost(userID int64, title, content string, categoryIDs []int64) (int64, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return 0, err
	}
	defer tx.Rollback()

	res, err := tx.Exec(
		`INSERT INTO posts (user_id, title, content) VALUES (?, ?, ?)`,
		userID, title, content,
	)
	if err != nil {
		return 0, err
	}
	postID, err := res.LastInsertId()
	if err != nil {
		return 0, err
	}
	for _, catID := range categoryIDs {
		if _, err := tx.Exec(
			`INSERT INTO post_categories (post_id, category_id) VALUES (?, ?)`, postID, catID,
		); err != nil {
			return 0, err
		}
	}
	return postID, tx.Commit()
}

// PostFilter selects which posts ListPosts returns. Zero value = all posts.
type PostFilter struct {
	CategoryID      int64 // 0 = any
	CreatedByUserID int64 // 0 = any
	LikedByUserID   int64 // 0 = any
	ViewerID        int64 // 0 = anonymous; used to fill Post.MyVote
}

func (s *Store) ListPosts(f PostFilter) ([]models.Post, error) {
	query := `
		SELECT DISTINCT p.id, p.user_id, u.username, p.title, p.content, p.created_at
		FROM posts p
		JOIN users u ON u.id = p.user_id`
	var args []any
	var where []string

	if f.CategoryID != 0 {
		query += ` JOIN post_categories pc ON pc.post_id = p.id`
		where = append(where, `pc.category_id = ?`)
		args = append(args, f.CategoryID)
	}
	if f.CreatedByUserID != 0 {
		where = append(where, `p.user_id = ?`)
		args = append(args, f.CreatedByUserID)
	}
	if f.LikedByUserID != 0 {
		query += ` JOIN post_likes pl ON pl.post_id = p.id AND pl.value = 1`
		where = append(where, `pl.user_id = ?`)
		args = append(args, f.LikedByUserID)
	}
	for i, cond := range where {
		if i == 0 {
			query += ` WHERE ` + cond
		} else {
			query += ` AND ` + cond
		}
	}
	query += ` ORDER BY p.created_at DESC`

	rows, err := s.db.Query(query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var posts []models.Post
	for rows.Next() {
		var p models.Post
		if err := rows.Scan(&p.ID, &p.UserID, &p.Author, &p.Title, &p.Content, &p.CreatedAt); err != nil {
			return nil, err
		}
		posts = append(posts, p)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	for i := range posts {
		if err := s.hydratePost(&posts[i], f.ViewerID); err != nil {
			return nil, err
		}
	}
	return posts, nil
}

func (s *Store) GetPost(id, viewerID int64) (*models.Post, error) {
	p := &models.Post{}
	err := s.db.QueryRow(`
		SELECT p.id, p.user_id, u.username, p.title, p.content, p.created_at
		FROM posts p JOIN users u ON u.id = p.user_id WHERE p.id = ?`, id,
	).Scan(&p.ID, &p.UserID, &p.Author, &p.Title, &p.Content, &p.CreatedAt)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	if err := s.hydratePost(p, viewerID); err != nil {
		return nil, err
	}
	return p, nil
}

func (s *Store) hydratePost(p *models.Post, viewerID int64) error {
	rows, err := s.db.Query(`
		SELECT c.id, c.name FROM categories c
		JOIN post_categories pc ON pc.category_id = c.id
		WHERE pc.post_id = ? ORDER BY c.name`, p.ID)
	if err != nil {
		return err
	}
	for rows.Next() {
		var c models.Category
		if err := rows.Scan(&c.ID, &c.Name); err != nil {
			rows.Close()
			return err
		}
		p.Categories = append(p.Categories, c)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return err
	}

	if err := s.db.QueryRow(
		`SELECT COALESCE(SUM(value = 1), 0), COALESCE(SUM(value = -1), 0) FROM post_likes WHERE post_id = ?`,
		p.ID,
	).Scan(&p.Likes, &p.Dislikes); err != nil {
		return err
	}

	if viewerID != 0 {
		var v int
		err := s.db.QueryRow(
			`SELECT value FROM post_likes WHERE post_id = ? AND user_id = ?`, p.ID, viewerID,
		).Scan(&v)
		if err != nil && !errors.Is(err, sql.ErrNoRows) {
			return err
		}
		p.MyVote = v
	}
	return nil
}

// --- Comments ---------------------------------------------------------

func (s *Store) CreateComment(postID, userID int64, content string) (int64, error) {
	res, err := s.db.Exec(
		`INSERT INTO comments (post_id, user_id, content) VALUES (?, ?, ?)`,
		postID, userID, content,
	)
	if err != nil {
		return 0, err
	}
	return res.LastInsertId()
}

func (s *Store) ListComments(postID, viewerID int64) ([]models.Comment, error) {
	rows, err := s.db.Query(`
		SELECT c.id, c.post_id, c.user_id, u.username, c.content, c.created_at
		FROM comments c JOIN users u ON u.id = c.user_id
		WHERE c.post_id = ? ORDER BY c.created_at ASC`, postID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var comments []models.Comment
	for rows.Next() {
		var c models.Comment
		if err := rows.Scan(&c.ID, &c.PostID, &c.UserID, &c.Author, &c.Content, &c.CreatedAt); err != nil {
			return nil, err
		}
		comments = append(comments, c)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	for i := range comments {
		c := &comments[i]
		if err := s.db.QueryRow(
			`SELECT COALESCE(SUM(value = 1), 0), COALESCE(SUM(value = -1), 0) FROM comment_likes WHERE comment_id = ?`,
			c.ID,
		).Scan(&c.Likes, &c.Dislikes); err != nil {
			return nil, err
		}
		if viewerID != 0 {
			var v int
			err := s.db.QueryRow(
				`SELECT value FROM comment_likes WHERE comment_id = ? AND user_id = ?`, c.ID, viewerID,
			).Scan(&v)
			if err != nil && !errors.Is(err, sql.ErrNoRows) {
				return nil, err
			}
			c.MyVote = v
		}
	}
	return comments, nil
}

// --- Likes --------------------------------------------------------------

// VotePost sets the viewer's vote to value (1 or -1). Voting the same value
// again clears the vote (toggle off).
func (s *Store) VotePost(userID, postID int64, value int) error {
	var existing int
	err := s.db.QueryRow(
		`SELECT value FROM post_likes WHERE user_id = ? AND post_id = ?`, userID, postID,
	).Scan(&existing)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		_, err = s.db.Exec(
			`INSERT INTO post_likes (user_id, post_id, value) VALUES (?, ?, ?)`, userID, postID, value)
		return err
	case err != nil:
		return err
	case existing == value:
		_, err = s.db.Exec(`DELETE FROM post_likes WHERE user_id = ? AND post_id = ?`, userID, postID)
		return err
	default:
		_, err = s.db.Exec(
			`UPDATE post_likes SET value = ? WHERE user_id = ? AND post_id = ?`, value, userID, postID)
		return err
	}
}

func (s *Store) VoteComment(userID, commentID int64, value int) error {
	var existing int
	err := s.db.QueryRow(
		`SELECT value FROM comment_likes WHERE user_id = ? AND comment_id = ?`, userID, commentID,
	).Scan(&existing)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		_, err = s.db.Exec(
			`INSERT INTO comment_likes (user_id, comment_id, value) VALUES (?, ?, ?)`, userID, commentID, value)
		return err
	case err != nil:
		return err
	case existing == value:
		_, err = s.db.Exec(`DELETE FROM comment_likes WHERE user_id = ? AND comment_id = ?`, userID, commentID)
		return err
	default:
		_, err = s.db.Exec(
			`UPDATE comment_likes SET value = ? WHERE user_id = ? AND comment_id = ?`, value, userID, commentID)
		return err
	}
}

func (s *Store) PostExists(id int64) (bool, error) {
	var n int
	err := s.db.QueryRow(`SELECT COUNT(*) FROM posts WHERE id = ?`, id).Scan(&n)
	return n > 0, err
}

