	"net/http"
	"strconv"
	"strings"

	"forum/internal/store"
)

const postsPerPage = 9

func (h *Handlers) listPosts(w http.ResponseWriter, r *http.Request) {
	user := userFrom(r)
	f := store.PostFilter{}
	if user != nil {
		f.ViewerID = user.ID
	}

	q := r.URL.Query()
