			return
		}
		f.CategoryID = id
	}
	switch q.Get("filter") {
	case "created":
		if user == nil {
			http.Error(w, "must be logged in", http.StatusUnauthorized)
			return
		}
		f.CreatedByUserID = user.ID
	case "liked":
		if user == nil {
			http.Error(w, "must be logged in", http.StatusUnauthorized)
			return
		}
		f.LikedByUserID = user.ID
	}
	page := 1
	if v := q.Get("page"); v != "" {
		p, err := strconv.Atoi(v)
		if err != nil || p < 1 {
			http.Error(w, "invalid page", http.StatusBadRequest)
			return
		}
		page = p
	}
