		"Posts":      posts,
		"Categories": categories,
		"Filter":     q.Get("filter"),
		"CategoryID": f.CategoryID,
		"Page":       page,
		"TotalPages": totalPages,
		"PrevURL":    prevURL,
		"NextURL":    nextURL,
	})
}

func pageURL(r *http.Request, page int) string {
	q := r.URL.Query()
	if page <= 1 {
		q.Del("page")
	} else {
		q.Set("page", strconv.Itoa(page))
	}
	if encoded := q.Encode(); encoded != "" {
		return "/?" + encoded
	}
	return "/"
}

