package store

import (
	"testing"

	"forum/internal/db"
)

func TestVotePostToggle(t *testing.T) {
	conn, err := db.Open(":memory:")
	if err != nil {
		t.Fatal(err)
	}
	defer conn.Close()
	s := New(conn)

	userID, err := s.CreateUser("a@a.com", "alice", "hash")
	if err != nil {
		t.Fatal(err)
	}
	postID, err := s.CreatePost(userID, "t", "c", nil)
	if err != nil {
		t.Fatal(err)
	}

	if err := s.VotePost(userID, postID, 1); err != nil {
		t.Fatal(err)
	}
	p, err := s.GetPost(postID, userID)
	if err != nil {
		t.Fatal(err)
	}
	if p.Likes != 1 || p.Dislikes != 0 || p.MyVote != 1 {
		t.Fatalf("after like: got likes=%d dislikes=%d myVote=%d", p.Likes, p.Dislikes, p.MyVote)
	}

	// voting the same value again toggles it off
	if err := s.VotePost(userID, postID, 1); err != nil {
		t.Fatal(err)
	}
	p, err = s.GetPost(postID, userID)
	if err != nil {
		t.Fatal(err)
	}
	if p.Likes != 0 || p.MyVote != 0 {
		t.Fatalf("after untoggle: got likes=%d myVote=%d", p.Likes, p.MyVote)
	}

	// switching straight from no vote to dislike
	if err := s.VotePost(userID, postID, -1); err != nil {
		t.Fatal(err)
	}
	p, err = s.GetPost(postID, userID)
	if err != nil {
		t.Fatal(err)
	}
	if p.Dislikes != 1 || p.MyVote != -1 {
		t.Fatalf("after dislike: got dislikes=%d myVote=%d", p.Dislikes, p.MyVote)
	}
}

